BEGIN TRANSACTION;
CREATE TABLE ZAPPRULE ( Z_PK INTEGER PRIMARY KEY, Z_ENT INTEGER, Z_OPT INTEGER, ZDONOTRESTOREKEYBOARD INTEGER, ZDORESTOREKEYBOARD INTEGER, ZHIDEINDICATOR INTEGER, ZREMOVED INTEGER, ZCREATEDAT TIMESTAMP, ZBUNDLEID VARCHAR, ZBUNDLENAME VARCHAR, ZINPUTSOURCEID VARCHAR, ZURL VARCHAR );
CREATE TABLE ZBROWSERRULE ( Z_PK INTEGER PRIMARY KEY, Z_ENT INTEGER, Z_OPT INTEGER, ZDISABLED INTEGER, ZHIDEINDICATOR INTEGER, ZTYPEVALUE INTEGER, ZCREATEDAT TIMESTAMP, ZINPUTSOURCEID VARCHAR, ZKEYBOARDRESTORESTRATEGYRAW VARCHAR, ZSAMPLE VARCHAR, ZVALUE VARCHAR );
CREATE TABLE ZHOTKEYGROUP ( Z_PK INTEGER PRIMARY KEY, Z_ENT INTEGER, Z_OPT INTEGER, ZCREATEDAT TIMESTAMP, ZID VARCHAR, ZINPUTSOURCEIDS VARCHAR );
CREATE TABLE ZKEYBOARDCONFIG ( Z_PK INTEGER PRIMARY KEY, Z_ENT INTEGER, Z_OPT INTEGER, ZBGCOLORHEX VARCHAR, ZID VARCHAR, ZTEXTCOLORHEX VARCHAR );
CREATE TABLE Z_METADATA (Z_VERSION INTEGER PRIMARY KEY, Z_UUID VARCHAR(255), Z_PLIST BLOB);
CREATE TABLE Z_MODELCACHE (Z_CONTENT BLOB);
CREATE TABLE Z_PRIMARYKEY (Z_ENT INTEGER PRIMARY KEY, Z_NAME VARCHAR, Z_SUPER INTEGER, Z_MAX INTEGER);
COMMIT;
